const SENTS=[
/* ===== 第 1 周：简单句骨架 ===== */
{en:"Many students spend too much time on their phones.",cut:"Many students / spend too much time / on their phones.",trunk:"Many students spend time.（spend + 时间 + on sth）",zh:"很多学生花太多时间在手机上。",pt:"spend time on sth；too much 修饰不可数名词"},
{en:"The teacher asked us to hand in the report before Friday.",cut:"The teacher / asked us / to hand in the report / before Friday.",trunk:"The teacher asked us to hand in the report.（ask sb to do sth）",zh:"老师要求我们在周五前交报告。",pt:"ask sb to do sth；before Friday 是时间状语，中文要前置"},
{en:"Reading is a good way to improve your English.",cut:"Reading / is / a good way / to improve your English.",trunk:"Reading is a good way.（动名词作主语）",zh:"阅读是提高英语的好方法。",pt:"动名词作主语；to do 作定语修饰 way"},
{en:"There are more and more people living in big cities.",cut:"There are / more and more people / living in big cities.",trunk:"There are people.（living in big cities 作定语）",zh:"越来越多的人住在大城市。",pt:"there be + doing 作后置定语；more and more 比较级叠用"},

/* ===== 第 2 周：定语、状语的位置 ===== */
{en:"The book on the desk belongs to my sister.",cut:"The book / on the desk / belongs to my sister.",trunk:"The book belongs to my sister.（主语是 book）",zh:"桌上的那本书是我姐姐的。",pt:"介词短语作定语后置，中文要译成前置的“……的”"},
{en:"He usually gets up early in order to catch the first bus.",cut:"He usually gets up early / in order to catch the first bus.",trunk:"He gets up early.",zh:"他通常早起，为了赶上第一班公交。",pt:"in order to 表目的，中文常译成“为了……”并前置"},
{en:"With the development of technology, our life has become much easier.",cut:"With the development of technology / our life / has become / much easier.",trunk:"our life has become easier.",zh:"随着科技的发展，我们的生活变得容易多了。",pt:"with 短语作状语；much 修饰比较级"},
{en:"People in different countries have different ways of greeting each other.",cut:"People in different countries / have / different ways / of greeting each other.",trunk:"People have ways.",zh:"不同国家的人有不同的问候方式。",pt:"of + doing 作定语，中文译成前置"},

/* ===== 第 3 周：并列句与时态 ===== */
{en:"He has lived in Nanjing since he graduated from college.",cut:"He has lived in Nanjing / since he graduated from college.",trunk:"He has lived in Nanjing.",zh:"他大学毕业后一直住在南京。",pt:"since 从句用一般过去，主句用现在完成"},
{en:"The meeting had already started when we arrived at the hall.",cut:"The meeting had already started / when we arrived at the hall.",trunk:"The meeting had started.",zh:"我们到大厅时，会议已经开始了。",pt:"过去完成 had done 表示“过去的过去”"},
{en:"You can either take the subway or take a taxi.",cut:"You can / either take the subway / or take a taxi.",trunk:"You can take the subway or a taxi.",zh:"你可以坐地铁，也可以打车。",pt:"either…or… 并列两个动作"},
{en:"It was raining hard, so we decided to stay at home.",cut:"It was raining hard / so we decided to stay at home.",trunk:"It was raining; we decided to stay.",zh:"雨下得很大，所以我们决定待在家里。",pt:"so 连接并列句；decide to do；stay at home 不加 to"},

/* ===== 第 4 周：定语从句 ===== */
{en:"The number of students who study abroad has increased rapidly in recent years.",cut:"The number of students / who study abroad / has increased rapidly / in recent years.",trunk:"The number … has increased.（主语是 number，不是 students）",zh:"近年来，出国留学的学生人数迅速增加。",pt:"主语被定语从句隔开；the number of 谓语用单数"},
{en:"This is the village where my grandparents used to live.",cut:"This is the village / where my grandparents used to live.",trunk:"This is the village.",zh:"这就是我祖父母过去住的村子。",pt:"where 引导定语从句作地点状语；used to do 过去常常"},
{en:"The man whose car was stolen reported to the police at once.",cut:"The man / whose car was stolen / reported to the police / at once.",trunk:"The man reported to the police.",zh:"车被偷的那个人立刻报了警。",pt:"whose 表所属关系；主谓被从句隔开"},
{en:"The report, which was published last week, has attracted wide attention.",cut:"The report / which was published last week / has attracted wide attention.",trunk:"The report has attracted attention.",zh:"这份上周发布的报告引起了广泛关注。",pt:"非限制性定语从句用逗号隔开，可用 which 指物"},

/* ===== 第 5 周：状语从句 ===== */
{en:"Although online learning is convenient, many students find it difficult to stay focused without a teacher's supervision.",cut:"Although online learning is convenient / many students find it difficult / to stay focused / without a teacher's supervision.",trunk:"many students find it difficult to stay focused.（it 是形式宾语）",zh:"虽然线上学习很方便，但很多学生发现，没有老师监督就很难保持专注。",pt:"Although 不与 but 连用；find it difficult to do 形式宾语"},
{en:"If you want to improve your speaking, you must practice every day.",cut:"If you want to improve your speaking / you must practice / every day.",trunk:"you must practice.",zh:"如果你想提高口语，就必须每天练习。",pt:"if 条件从句在前，主句用情态动词"},
{en:"As soon as the bell rang, the students rushed out of the classroom.",cut:"As soon as the bell rang / the students rushed out / of the classroom.",trunk:"the students rushed out.",zh:"铃一响，学生们就冲出了教室。",pt:"as soon as 时间状语从句；rush out of 冲出"},
{en:"Now that you have made a decision, you should stick to it.",cut:"Now that you have made a decision / you should stick to it.",trunk:"you should stick to it.",zh:"既然你已经做了决定，就应该坚持下去。",pt:"now that 引导原因状语从句；stick to 坚持（to 是介词）"},

/* ===== 第 6 周：名词性从句与 it ===== */
{en:"What matters most is not how much you know but how well you can use it.",cut:"What matters most / is / not how much you know / but how well you can use it.",trunk:"What matters most is …（主语从句作主语）",zh:"最重要的不是你知道多少，而是你能用得多好。",pt:"what 在从句中作主语；not…but… 对称结构"},
{en:"It is important that everyone should follow the safety rules.",cut:"It is important / that everyone should follow the safety rules.",trunk:"It is important that…（it 是形式主语）",zh:"每个人都遵守安全规则，这一点很重要。",pt:"It is + adj. + that + (should) do 虚拟语气"},
{en:"Whether he will come to the party remains unknown.",cut:"Whether he will come to the party / remains unknown.",trunk:"Whether… remains unknown.（主语从句）",zh:"他是否会来参加聚会还不清楚。",pt:"whether 引导主语从句，不能用 if"},
{en:"We consider it necessary to protect the environment from pollution.",cut:"We consider it necessary / to protect the environment / from pollution.",trunk:"We consider it necessary to protect the environment.（it 形式宾语）",zh:"我们认为有必要保护环境免受污染。",pt:"consider it + adj. + to do；protect…from…"},

/* ===== 第 7 周：非谓语动词 ===== */
{en:"Walking along the river, I met an old friend of mine.",cut:"Walking along the river / I met / an old friend of mine.",trunk:"I met an old friend.（walking 的逻辑主语是 I）",zh:"沿着河边走的时候，我遇到了一位老朋友。",pt:"现在分词作时间状语，逻辑主语必须与主句一致"},
{en:"The problem discussed at the meeting is very important.",cut:"The problem / discussed at the meeting / is very important.",trunk:"The problem is important.",zh:"会上讨论的那个问题很重要。",pt:"过去分词作定语表被动，相当于 which was discussed"},
{en:"Having finished his homework, he went out to play football.",cut:"Having finished his homework / he went out / to play football.",trunk:"he went out.",zh:"做完作业后，他出去踢足球了。",pt:"having done 表示动作先于主句发生"},
{en:"To save time, we decided to take a taxi instead of the bus.",cut:"To save time / we decided to take a taxi / instead of the bus.",trunk:"we decided to take a taxi.",zh:"为了省时间，我们决定打车而不是坐公交。",pt:"to do 作目的状语；instead of + 名词"},

/* ===== 第 8 周：长句与插入语 ===== */
{en:"Researchers have found that people who exercise regularly are less likely to suffer from heart disease.",cut:"Researchers have found / that people / who exercise regularly / are less likely / to suffer from heart disease.",trunk:"Researchers have found that people are less likely to suffer…",zh:"研究人员发现，经常锻炼的人患心脏病的可能性更小。",pt:"宾语从句套定语从句；be less likely to do"},
{en:"Many companies, especially those in the technology sector, are looking for employees with strong communication skills.",cut:"Many companies / especially those in the technology sector / are looking for employees / with strong communication skills.",trunk:"Many companies are looking for employees.",zh:"很多公司，尤其是科技行业的公司，正在寻找沟通能力强的员工。",pt:"插入语用逗号隔开；those 替代 companies"},
{en:"The study suggests that the amount of time children spend on screens has a direct effect on their sleep.",cut:"The study suggests / that the amount of time / children spend on screens / has a direct effect / on their sleep.",trunk:"The study suggests that the amount of time has an effect.",zh:"该研究表明，孩子花在屏幕上的时间对他们的睡眠有直接影响。",pt:"省略关系词的定语从句：time (that) children spend；have an effect on"},
{en:"It is not the length of life but its quality that really counts.",cut:"It is / not the length of life / but its quality / that really counts.",trunk:"It is not the length of life but its quality that counts.（强调句，被强调部分是 not A but B）",zh:"真正重要的不是生命的长短，而是它的质量。",pt:"强调句 + not…but…；count 意为“重要”"},

/* ===== 第 9 周：翻译高频句式 ===== */
{en:"With the development of the Internet, online shopping has become part of our daily life.",cut:"With the development of the Internet / online shopping / has become / part of our daily life.",trunk:"online shopping has become part of our life.",zh:"随着互联网的发展，网上购物已成为我们日常生活的一部分。",pt:"with 短语作状语；现在完成时"},
{en:"Only by working hard can we achieve our goals.",cut:"Only by working hard / can we achieve / our goals.",trunk:"we can achieve our goals.（倒装还原后）",zh:"只有努力工作，我们才能实现目标。",pt:"only + 状语置于句首，主句部分倒装"},
{en:"It is reported that the new policy will take effect next month.",cut:"It is reported / that the new policy will take effect / next month.",trunk:"It is reported that…",zh:"据报道，新政策将于下月生效。",pt:"it 形式主语 + 被动；take effect 生效"},
{en:"The more you practice, the more confident you will become.",cut:"The more you practice / the more confident / you will become.",trunk:"you will become confident.",zh:"你练得越多，就会越自信。",pt:"the more…the more… 比较级叠用"},

/* ===== 第 10 周：综合 ===== */
{en:"Although the task was difficult, they managed to finish it on time.",cut:"Although the task was difficult / they managed to finish it / on time.",trunk:"they managed to finish it.",zh:"虽然任务很难，他们还是设法按时完成了。",pt:"manage to do 设法做成；on time 按时"},
{en:"What we need most at the moment is a clear plan rather than more discussion.",cut:"What we need most at the moment / is / a clear plan / rather than more discussion.",trunk:"What we need is a plan.",zh:"我们目前最需要的是一份清晰的计划，而不是更多的讨论。",pt:"主语从句 + rather than（而不是）"},
{en:"People who read regularly tend to have a larger vocabulary than those who seldom read.",cut:"People / who read regularly / tend to have a larger vocabulary / than those who seldom read.",trunk:"People tend to have a larger vocabulary.",zh:"经常阅读的人，词汇量往往比很少阅读的人更大。",pt:"tend to do；those 替代 people，避免重复"},
{en:"Not until we lose our health do we realize how important it is.",cut:"Not until we lose our health / do we realize / how important it is.",trunk:"we realize how important it is.",zh:"直到失去健康，我们才意识到它有多重要。",pt:"Not until 置于句首，主句部分倒装；how 引导宾语从句"}
];

